contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint salt) public payable {
        require(salt < type(uint256).max);
        uint pbt = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        assert(c.pastBlockTime() == 0 && address(c).balance == balBefore && pbt == c.pastBlockTime());
    }
    receive() external payable {}
}

